#include "travel_session.hpp"
#include "deals.hpp"
#include <iostream>
#define CHECK(x) do{if(!(x))throw std::runtime_error("Travel check failed "+std::to_string(__LINE__));}while(false)
int main(){using namespace perekup;Json cities={{"a",{{"id","a"},{"name","Москва"},{"lat",55.75},{"lon",37.62}}},{"b",{{"id","b"},{"name","Тула"},{"lat",54.19},{"lon",37.62}}}},cars=Json::object();Deals deals(cities,cars,"a",[]{return .5;});auto state=deals.fresh(1000000);auto before=state;CHECK(!departPublicTransport(state,cities,cars,"a","a","train")&&state==before);auto poor=state;poor["balance"]=0;auto poorBefore=poor;CHECK(!departPublicTransport(poor,cities,cars,"a","b","train")&&poor==poorBefore);CHECK(departPublicTransport(state,cities,cars,"a","b","train"));auto price=state["transport"]["trip"]["price"].get<Money>();CHECK(state["balance"]==100000-price);before=state;CHECK(!departPublicTransport(state,cities,cars,"a","b","plane")&&state==before);auto restored=Json::parse(state.dump());Transport transport(cities,cars,"a");transport.state=restored["transport"];transport.now=num(transport.state["trip"],"arrivesAt");CHECK(transport.tick());CHECK(transport.state["cityId"]=="b"&&transport.state["trip"].is_null());auto active=deals.fresh(1000000);active["chat"]={{"met",true},{"done",false}};before=active;CHECK(!departPublicTransport(active,cities,cars,"a","b","train")&&active==before);std::cout<<"PASS: route, insufficient funds, debit once, trip restore/arrival, active meeting guard\n";}
